<script setup>
import { onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import { getPerson } from '../api/person.js'; import BehaviorTimeline from '../components/BehaviorTimeline.vue'
const route=useRoute(),data=ref({behaviors:[],outfit:{},anomalies:[],pose:{}}); onMounted(async()=>data.value=await getPerson(route.params.videoId,route.params.personId))
