<template><div class="page"><div class="person-title"><div class="avatar">P{{ data.person_id }}</div><div><small>VIDEO #{{ data.video_id }}</small><h2>人物 {{ data.person_id }}</h2><p>{{ data.first_seen }}s - {{ data.last_seen }}s</p></div></div><section class="panel"><header>行为时间线</header><BehaviorTimeline :segments="data.behaviors"/></section><div class="detail-grid"><section class="panel"><header>Pose 状态</header><div class="metric-list"><div><span>关键点数量</span><strong>{{ data.pose?.keypoint_count }}</strong></div><div><span>Pose 记录</span><strong>{{ data.pose?.record_count }}</strong></div><div><span>身体状态</span><strong>{{ data.pose?.status }}</strong></div></div></section><section class="panel"><header>穿搭信息</header><div class="outfit-grid"><div><small>上衣</small><strong>{{ data.outfit?.upper_color }} · {{ data.outfit?.upper_type }}</strong><span>{{ data.outfit?.upper_sleeve }}</span></div><div><small>下装</small><strong>{{ data.outfit?.lower_color }} · {{ data.outfit?.lower_type }}</strong><span>{{ data.outfit?.lower_length }}</span></div></div></section></div><section class="panel"><header>异常事件</header><el-table :data="data.anomalies"><el-table-column prop="event" label="事件"/><el-table-column prop="severity" label="级别"/><el-table-column prop="start_time" label="开始时间(s)"/><el-table-column prop="end_time" label="结束时间(s)"/><el-table-column label="置信度"><template #default="s">{{ (s.row.confidence*100).toFixed(1) }}%</template></el-table-column></el-table></section></div></template>
